// 聽力題庫：Part 2 應答問題 + Part 3 對話 + Part 4 短講
// 音訊由瀏覽器語音合成（speechSynthesis）即時朗讀，作答前不顯示文字稿

// Part 2：聽問句，從三個口說選項中選出最合適的回應（900+ 常考間接回應與陷阱）
const PART2 = [
  { q: "Where should I submit my expense report?", opts: ["Through the expense portal on the company intranet.", "About fifty dollars for the taxi and meals.", "The expenses were higher than last month's."], ans: 0, exp: "問「在哪裡交」，答「透過公司內部網站的報帳系統」。「About fifty dollars…」答的是金額；「The expenses were higher…」用 expense 做同字陷阱，沒回答在哪裡交。" },
  { q: "The client meeting has been moved to Thursday, hasn't it?", opts: ["Yes, the client had a scheduling conflict on Wednesday.", "He moved to Chicago with his family last year.", "In the conference room on the fifth floor."], ans: 0, exp: "附加問句確認會議是否改到週四：「是的，客戶週三時間衝突」。「He moved to Chicago…」用 moved 做同字陷阱；「In the conference room…」答的是地點。" },
  { q: "Why don't we order more toner for the printer?", opts: ["Good idea — I'll call the supplier.", "Because the last order arrived two days late.", "A ten-page document in color."], ans: 0, exp: "Why don't we…? 是提議，回答「好主意，我來聯絡廠商」。用 Because 開頭回答提議是常見陷阱；「A ten-page document…」用 printer 相關字聯想，答非所問。" },
  { q: "Who's leading the training session this afternoon?", opts: ["It's been postponed until next week.", "In the main auditorium on the second floor.", "About two hours, including a short break."], ans: 0, exp: "問誰帶訓練，間接回答「延到下週了」（今天下午不會有人帶）。另外兩個分別答地點和時間長度。" },
  { q: "Would you like the aisle seat or the window seat?", opts: ["The aisle, please.", "Yes, I would.", "It's a long flight."], ans: 0, exp: "選擇疑問句（A or B）必須擇一回答，不能用 Yes/No。「Yes, I would.」是最典型的陷阱。" },
  { q: "How often does the shuttle run downtown?", opts: ["Every twenty minutes.", "It runs on diesel.", "Since this morning."], ans: 0, exp: "How often 問頻率，答「每二十分鐘一班」。「It runs on diesel」用 run 做同字陷阱；「Since this morning」答的是從什麼時候開始。" },
  { q: "Haven't you finished the budget proposal yet?", opts: ["I'm still waiting for the sales figures.", "Yes, it's not finished.", "We'll need a bigger budget next quarter."], ans: 0, exp: "否定疑問句問「還沒完成嗎」，間接回答「還在等銷售數字」（所以還沒完成）。「Yes, it's not finished」前後矛盾；「We'll need a bigger budget…」用 budget 做同字陷阱。" },
  { q: "Could you forward me the agenda before the call?", opts: ["Sure, I'll send it right away.", "Four items.", "He called yesterday."], ans: 0, exp: "請對方轉寄議程，回答「好，馬上寄」。「Four items」描述議程內容，沒有回應請求；「He called yesterday」用 call 做同字陷阱。" },
  { q: "When will the renovations be completed?", opts: ["You'd have to ask the contractor.", "On the fourth floor.", "It cost a lot."], ans: 0, exp: "問什麼時候完工，間接回答「要問承包商」（我不知道）。另外兩個分別答地點和費用。" },
  { q: "Do you want me to book the conference room, or has that been done?", opts: ["Tanya already reserved it.", "A room with a view of the harbor.", "Yes, please do both of them."], ans: 0, exp: "選擇疑問句（要我訂，還是已經訂了？），回答「Tanya 已經訂了」。選擇疑問句不能用 Yes 回答；「A room with a view…」用 room 做同字陷阱。" },
  { q: "This café is pretty crowded, isn't it?", opts: ["There's another one around the corner.", "I'd like a coffee with milk, please.", "No, it's the most crowded one in town."], ans: 0, exp: "附加問句說「很擠吧」，間接回應「轉角還有另一家」（建議換一家）。「No, it's the most crowded…」前後矛盾；點咖啡是用 café 聯想，答非所問。" },
  { q: "Whose laptop is this in the meeting room?", opts: ["It might be Karen's — she was just there.", "It's the newest model with a larger screen.", "On the table next to the projector."], ans: 0, exp: "Whose 問是誰的，回答「可能是 Karen 的」。「It's the newest model…」描述筆電；「On the table…」答的是位置。" },
  { q: "Should we take the highway or the local roads?", opts: ["The highway's faster this time of day.", "Yes, let's leave right after the lunch meeting.", "I took the train to work yesterday."], ans: 0, exp: "選擇疑問句（高速公路還是一般道路），回答「這個時段高速公路比較快」。選擇疑問句不能用 Yes 回答；「I took the train…」用 took 做同字陷阱。" },
  { q: "The quarterly figures look better than expected.", opts: ["Yes, sales really picked up in the last two months.", "We publish them on a quarterly basis.", "I expected you to arrive much earlier."], ans: 0, exp: "對方說季度數字比預期好，回應「是啊，最近兩個月業績大幅回升」。「on a quarterly basis」用 quarterly 做同字陷阱；「I expected you…」用 expected 做同字陷阱。" },
  { q: "How do I get reimbursed for the conference fees?", opts: ["Just submit the receipts to accounting.", "It was a very informative conference.", "By next Friday at the very latest, I think."], ans: 0, exp: "How 問如何報帳，回答「把收據交給會計」。「It was a very informative conference」用 conference 做同字陷阱；「By next Friday…」答的是期限。" },
  { q: "Why was the product launch delayed?", opts: ["There was an issue with the packaging.", "At the convention center downtown.", "It launched successfully in three countries."], ans: 0, exp: "Why 問延期原因，回答「包裝出了問題」。「At the convention center」答地點；「It launched successfully」和「延期」矛盾。" },
  { q: "Has the marketing report been finalized?", opts: ["Dana's reviewing the last section now.", "The marketing department is on the third floor.", "Yes, a financial report."], ans: 0, exp: "問報告定稿了沒，間接回答「Dana 正在看最後一節」（還沒定稿）。「The marketing department is…」用 marketing 做同字陷阱，答的是地點；「Yes, a financial report」答非所問。" },
  { q: "When does the pharmacy on Fifth Street close?", opts: ["It's open around the clock.", "Near the bank.", "To pick up a prescription."], ans: 0, exp: "When 問幾點關門，間接回答「24 小時營業」。「Near the bank」答地點；「To pick up a prescription」答目的。" },
  { q: "Why don't you join us for lunch at the new bistro?", opts: ["I wish I could, but I'm on a deadline.", "A table for six by the window, please.", "The bistro opened on Main Street in May."], ans: 0, exp: "邀請一起吃午餐，委婉拒絕「我也想，但在趕期限」。「A table for six…」是訂位用語，答非所問；「The bistro opened…」用 bistro 做同字陷阱，沒有回應邀請。" },
  { q: "Who approved the overtime request?", opts: ["It didn't need approval.", "About ten hours.", "Over the weekend."], ans: 0, exp: "Who 問誰核准，間接回答「這不需要核准」。另外兩個分別答時數和時間。" },
  { q: "Where can I find the safety guidelines?", opts: ["They're posted on the bulletin board.", "By the end of the day, if possible.", "We've maintained a safe workplace for years."], ans: 0, exp: "Where 問在哪裡找得到，回答「貼在公告欄上」。「By the end of the day」答時間；「a safe workplace」用 safety／safe 做同字陷阱。" },
  { q: "You've met the new branch manager, haven't you?", opts: ["Briefly, at the orientation.", "It's a management position.", "Yes, I'll meet the deadline."], ans: 0, exp: "附加問句：「見過，在新人訓練時短暫見過」。「I'll meet the deadline」用 meet 的多義陷阱（趕上期限）。" },
  { q: "Would you mind switching shifts with me on Friday?", opts: ["Not at all — I'm free that day.", "Yes, the light switch is by the door.", "During the night shift at the warehouse."], ans: 0, exp: "Would you mind…? 回答 Not at all 表示「不介意」，也就是答應。「the light switch」用 switch 做同字陷阱；「During the night shift…」用 shift 做同字陷阱。" },
  { q: "How many people signed up for the wellness program?", opts: ["I don't know — the list hasn't been posted yet.", "Please sign at the bottom of the form.", "It's a great program for new employees."], ans: 0, exp: "How many 問人數，間接回答「不知道，名單還沒公布」。「sign at the bottom」用 sign 做同字陷阱；「It's a great program…」用 program 做同字陷阱。" },
  { q: "Where did you put the quarterly sales report?", opts: ["I emailed it to you this morning.", "Sales were about three percent higher.", "It was quite detailed and well written."], ans: 0, exp: "Where 問報告放哪裡，間接回答「今天早上寄給你了」。另外兩個描述報告內容，沒回答在哪裡。" },
  { q: "Isn't the new cafeteria opening this week?", opts: ["No, it's been pushed back a month.", "On the second floor, next to the gym.", "Yes, I opened the window."], ans: 0, exp: "否定疑問句問「不是這週開幕嗎」，回答「沒有，延後一個月了」。「On the second floor…」答地點；「I opened the window」用 open 做同字陷阱。" },
  { q: "Should I email the client or call them directly?", opts: ["A phone call would be more personal.", "Yes, please do that.", "The client was very satisfied with the results."], ans: 0, exp: "選擇疑問句（寄信還是打電話），回答「打電話比較有誠意」。選擇疑問句不能用 Yes 回答；「The client was very satisfied…」用 client 做同字陷阱。" },
  { q: "Who's responsible for ordering office supplies?", opts: ["That's handled by the admin team.", "In the storage room.", "Every two weeks."], ans: 0, exp: "Who 問誰負責，回答「行政團隊負責」。另外兩個分別答地點和頻率。" },
  { q: "The projector in Room B isn't working again.", opts: ["I'll put in a maintenance request.", "Yes, it's a great room for presentations.", "About two hours long, including questions."], ans: 0, exp: "對方說投影機又壞了，回應「我來提出維修申請」。「it's a great room」用 room 做同字陷阱；「About two hours long」答時間長度。" },
  { q: "Why has the delivery been delayed?", opts: ["The supplier ran out of stock.", "By express courier.", "To the warehouse."], ans: 0, exp: "Why 問延遲原因，回答「供應商缺貨」。另外兩個分別答運送方式和目的地。" },
  { q: "Could you recommend a good hotel near the airport?", opts: ["The Grandview usually has great rates.", "Yes, I flew there for a conference last week.", "It's a long flight, so bring a book."], ans: 0, exp: "請對方推薦飯店，回答「Grandview 的價格通常很好」。「I flew there…」「It's a long flight…」都用 airport 聯想到飛行，答非所問。" },
  { q: "Do you know when the shipment will clear customs?", opts: ["It should be released by Thursday.", "At the port, in a refrigerated container.", "A large container of office furniture."], ans: 0, exp: "問何時通關，回答「週四前應該會放行」。「At the port…」答地點；「A large container…」描述貨物，沒回答時間。" },
  { q: "Haven't the new brochures been printed yet?", opts: ["They'll be ready this afternoon.", "The printer is on the second floor.", "In the marketing office."], ans: 0, exp: "否定疑問句：「今天下午就會好」表示還沒印好。「The printer is on the second floor」是用 printed／printer 的同字陷阱；「In the marketing office」答的是地點。" },
  { q: "Would you prefer the morning or the afternoon session?", opts: ["The morning works better for me.", "Yes, I'd love to attend the session.", "It lasts about two hours with a break."], ans: 0, exp: "選擇疑問句（上午還是下午），回答「上午比較方便」。選擇疑問句不能用 Yes 回答；「It lasts about two hours…」答時間長度。" },
  { q: "How often is the equipment serviced?", opts: ["Once every six months.", "By an outside contractor.", "In the basement."], ans: 0, exp: "How often 問頻率，「每六個月一次」。「By an outside contractor」答執行者；「In the basement」答地點。" },
  { q: "Where can I get my parking validated?", opts: ["At the reception desk in the lobby.", "For up to three hours.", "It costs five dollars."], ans: 0, exp: "Where 問停車券在哪裡蓋章，回答「在大廳的接待櫃檯」。另外兩個分別答時間長度和費用。" },
  { q: "The client wants to move the meeting up to Monday.", opts: ["I'll check if the room's free.", "Yes, it was a productive meeting.", "The movers arrive on Monday morning."], ans: 0, exp: "客戶想把會議提前到週一，回應「我來看看會議室有沒有空」。「it was a productive meeting」用過去式描述會議；「The movers…」用 move 做同字陷阱。" },
  { q: "Why don't we outsource the translation work?", opts: ["That might actually save us time.", "In several different languages, I think.", "It was translated into French last year."], ans: 0, exp: "Why don't we…? 提議外包翻譯，回應「那說不定能省時間」。另外兩個用 translation 聯想，答非所問。" },
  { q: "Has anyone confirmed the venue for the awards dinner?", opts: ["Karen is finalizing it today.", "It was a lovely evening, wasn't it?", "About two hundred guests are expected."], ans: 0, exp: "問場地確認了沒，回答「Karen 今天會確定」。「It was a lovely evening」用過去式描述晚宴；「About two hundred guests」答人數。" },
  { q: "Which supplier offered the better price?", opts: ["We're still comparing the two quotes.", "By the end of the week at the latest.", "In bulk quantities only."], ans: 0, exp: "Which 問哪家價格比較好，間接回答「還在比較兩份報價」。另外兩個分別答期限和數量。" },
  { q: "You're attending the trade show in Berlin, aren't you?", opts: ["Yes, my flight leaves Tuesday.", "It was informative.", "At the convention center."], ans: 0, exp: "附加問句確認是否參加柏林展覽，回答「是的，我週二的班機」。「It was informative」用過去式，答非所問；「At the convention center」答地點。" },
  { q: "Should the report be printed in color or black and white?", opts: ["Color would look more professional.", "Yes, ten copies, please.", "By tomorrow morning, if that's possible."], ans: 0, exp: "選擇疑問句（彩色還是黑白），回答「彩色看起來比較專業」。選擇疑問句不能用 Yes 回答；「By tomorrow morning」答期限。" },
  { q: "How was the response to the customer survey?", opts: ["Better than we anticipated.", "By email and by phone.", "Around fifty questions in total."], ans: 0, exp: "How was… 問反應如何，回答「比預期好」。「By email and by phone」答方式；「Around fifty questions」答題數。" },
  { q: "Where should I store these confidential files?", opts: ["In the locked cabinet in my office.", "For at least seven years, by law.", "They contain highly sensitive information."], ans: 0, exp: "Where 問放在哪裡，回答「我辦公室上鎖的櫃子」。「For at least seven years」答保存期限；「They contain highly sensitive information」用 confidential 聯想，沒回答在哪裡。" },
  { q: "Didn't the maintenance crew fix the elevator?", opts: ["They're coming back tomorrow.", "The crew had lunch in the cafeteria.", "On the fifth and sixth floors."], ans: 0, exp: "否定疑問句問「維修人員不是修好了嗎」，間接回答「他們明天會再來」（還沒修好）。「The crew had lunch…」用 crew 做同字陷阱；「On the fifth and sixth floors」答地點。" },
  { q: "Would you like me to book a taxi or arrange a shuttle?", opts: ["A shuttle would be more economical.", "Yes, right away, please.", "To the airport by six o'clock tomorrow."], ans: 0, exp: "選擇疑問句（計程車還是接駁車），回答「接駁車比較省錢」。選擇疑問句不能用 Yes 回答；「To the airport…」答目的地。" },
  { q: "Why was the budget meeting canceled?", opts: ["The director had a scheduling conflict.", "In the main boardroom on the top floor.", "For about an hour every Monday."], ans: 0, exp: "Why 問會議取消的原因，回答「主管時間衝突」。另外兩個分別答地點和時間。" },
  { q: "How do I apply for the leadership program?", opts: ["There's a form on the intranet.", "It runs for six months.", "About twenty participants."], ans: 0, exp: "How 問如何申請，回答「內部網站上有表格」。另外兩個分別答期間和人數。" },
  { q: "The printer is out of toner again.", opts: ["I'll order some more right away.", "Yes, it prints very quickly in color.", "On the third floor, next to the kitchen."], ans: 0, exp: "對方說印表機又沒碳粉了，回應「我馬上再訂」。「it prints very quickly」用 printer 聯想；「On the third floor…」答地點。" },
  { q: "Who approved this expense report?", opts: ["It still needs the director's signature.", "About three hundred dollars for the hotel.", "Last Thursday, before the meeting."], ans: 0, exp: "Who 問誰核准，間接回答「還需要主管簽名」（還沒核准）。另外兩個分別答金額和時間。" },
  { q: "Isn't this the last day of the promotion?", opts: ["No, it runs through Sunday.", "At all of our locations nationwide.", "Twenty percent off all winter coats."], ans: 0, exp: "否定疑問句問「今天不是促銷最後一天嗎」，回答「不是，到週日」。另外兩個分別答地點和折扣內容。" },
  { q: "Where are the training sessions being held this year?", opts: ["They've moved to the downtown branch.", "Every Wednesday afternoon from two to four.", "By a certified instructor from headquarters."], ans: 0, exp: "Where 問在哪裡舉行，回答「搬到市中心分行了」。另外兩個分別答時間和講師。" },
  { q: "Could you send me the updated contact list?", opts: ["Sure, I'll forward it now.", "About fifty names.", "In alphabetical order."], ans: 0, exp: "請對方寄聯絡名單，回答「好，現在就轉寄」。另外兩個描述名單內容，沒回應請求。" },
  { q: "Why is the lobby closed off this morning?", opts: ["They're refinishing the floors.", "Until noon.", "Near the main entrance."], ans: 0, exp: "Why 問大廳為什麼封閉，回答「正在重新整修地板」。「Until noon」答到什麼時候；「Near the main entrance」答地點。" },
  { q: "Do you want to review the slides before the presentation?", opts: ["Yes, could you email them over?", "It went very well, thanks for asking.", "In the conference room on the second floor."], ans: 0, exp: "問要不要先看簡報，回答「好，可以寄給我嗎？」。「It went very well」用過去式說簡報（還沒發生）；「In the conference room…」答地點。" },
  { q: "How long has Ms. Tanaka been with the company?", opts: ["She joined about a decade ago.", "In the finance department.", "As a senior analyst."], ans: 0, exp: "How long 問在公司多久，回答「大約十年前加入」。另外兩個分別答部門和職位。" },
  { q: "Shouldn't we notify the clients about the price change?", opts: ["A notice is already being drafted.", "I changed my phone number last week.", "By about five percent for most items."], ans: 0, exp: "否定疑問句＋間接回應：「通知已經在草擬了」表示會通知。「I changed my phone number」用 change 做同字陷阱；「By about five percent」答的是漲幅。" },
  { q: "Where did the shipment get held up?", opts: ["Somewhere at the border crossing, I heard.", "For over a week, unfortunately.", "It was packed in sealed containers."], ans: 0, exp: "Where 問貨在哪裡被卡住，回答「聽說是在邊境關口」。「For over a week」答時間長度；「It was packed…」描述包裝。" },
  { q: "Would you rather lead the project or support it?", opts: ["I'd be happy to take the lead.", "Yes, it's an exciting project.", "Over the next quarter."], ans: 0, exp: "選擇疑問句擇一回答。「Yes, it's an exciting project」用 Yes 回答是陷阱。" },
  { q: "Why haven't the invoices been sent to accounting?", opts: ["I'm still waiting on two receipts.", "By the end of the day at the latest.", "In the top drawer of my desk."], ans: 0, exp: "Why 問發票為什麼還沒送會計，回答「還在等兩張收據」。「By the end of the day」答時間；「In the top drawer…」答地點。" },
  // ---- S2（2026-10-11）：新題 40 題，兩位獨立審查者盲解一致 ----
  { q: "When is the new branch opening?", opts: ["Sometime in early spring.", "On Maple Avenue, near the bank.", "Yes, it's a branch of the bank."], ans: 0, exp: "When 問時間，回答「春初的某個時候」。「On Maple Avenue…」答地點；「Yes, it's a branch…」用 Yes 回答 When 問句，而且 branch 是同字陷阱。", src: "S2" },
  { q: "Who's going to train the new interns?", opts: ["Ms. Okoro volunteered to do it.", "They start on Monday.", "The train leaves at noon."], ans: 0, exp: "Who 問誰負責訓練，回答「Okoro 女士自願擔任」。「They start on Monday」答時間；「The train leaves…」用 train 做同字陷阱（訓練／火車）。", src: "S2" },
  { q: "Where can I recharge my phone?", opts: ["There's an outlet behind the sofa.", "About two hours ago, before the meeting started.", "Yes, the charge was refunded."], ans: 0, exp: "Where 問在哪裡充電，回答「沙發後面有插座」。「About two hours ago」答時間；「the charge was refunded」用 charge 做同字陷阱（充電／費用）。", src: "S2" },
  { q: "Why was the meeting moved to Room 6?", opts: ["Room 4 is being painted.", "At two o'clock this afternoon.", "I moved here three years ago."], ans: 0, exp: "Why 問原因，回答「4 號會議室在油漆」。「At two o'clock…」答時間；「I moved here…」用 moved 做同字陷阱。", src: "S2" },
  { q: "How long will the inspection take?", opts: ["Most of the afternoon, I'd guess.", "The inspector arrives at nine.", "It's a long hallway."], ans: 0, exp: "How long 問需要多久，回答「我猜大概一個下午」。「The inspector arrives at nine」答幾點來；「It's a long hallway」用 long 做同字陷阱。", src: "S2" },
  { q: "Which hotel did you book for the conference?", opts: ["I haven't decided yet.", "Three nights, starting Tuesday.", "The conference was very useful."], ans: 0, exp: "Which 問訂哪家飯店，間接回答「還沒決定」。「Three nights…」答住幾晚；「The conference was very useful」用 conference 做同字陷阱。", src: "S2" },
  { q: "Would you like some help carrying those boxes?", opts: ["Thanks, they're heavier than they look.", "Yes, I'd like a box of pens.", "In the supply closet."], ans: 0, exp: "提議幫忙搬箱子，回答「謝謝，它們比看起來重」，表示接受幫忙。「a box of pens」用 box 做同字陷阱；「In the supply closet」答地點。", src: "S2" },
  { q: "Can you review my report before I submit it?", opts: ["Sure, send it over.", "It was reviewed by the board.", "The deadline was last month."], ans: 0, exp: "請對方幫忙看報告，回答「好，寄過來」。「It was reviewed by the board」用 review 做同字陷阱；「The deadline was last month」說期限已過，和「還沒交」的情況矛盾。", src: "S2" },
  { q: "Didn't Mr. Hill approve the budget yesterday?", opts: ["He's still reviewing a few items.", "A budget of ten thousand dollars.", "Yes, a budget hotel."], ans: 0, exp: "否定疑問句問「Hill 先生昨天不是核准了嗎」，間接回答「他還在看幾個項目」（還沒核准）。另外兩個用 budget 做同字陷阱，答非所問。", src: "S2" },
  { q: "Should we take a taxi or walk to the restaurant?", opts: ["It's only five minutes away.", "Yes, the restaurant was excellent.", "A table for four, please."], ans: 0, exp: "選擇疑問句（搭計程車還是走路），間接回答「只要五分鐘」（走路就好）。選擇疑問句不能用 Yes 回答；「A table for four」是訂位用語。", src: "S2" },
  { q: "The printer on the second floor is jammed again.", opts: ["I'll call the technician.", "Print two copies, please.", "On the second floor, next to the elevator."], ans: 0, exp: "對方說印表機又卡紙了，回應「我來找技術人員」。「Print two copies」用 print 聯想；「On the second floor…」重複題目的地點，答非所問。", src: "S2" },
  { q: "You've worked with this client before, haven't you?", opts: ["Yes, on last year's ad campaign.", "He works on the fifth floor.", "The client signed the contract last week."], ans: 0, exp: "附加問句確認以前是否合作過，回答「是的，在去年的廣告活動」。「He works on the fifth floor」用 work 做同字陷阱；「The client signed…」用 client 做同字陷阱。", src: "S2" },
  { q: "Why don't we hold the training session online?", opts: ["That would save on travel costs.", "Because the session was canceled.", "Online banking is convenient."], ans: 0, exp: "Why don't we…? 是提議，回答「那可以省下交通費」表示贊成。用 Because 回答提議是常見陷阱；「Online banking…」用 online 做同字陷阱。", src: "S2" },
  { q: "What time does the post office close today?", opts: ["At five thirty, I think.", "Next to the pharmacy.", "I posted it on the website."], ans: 0, exp: "What time 問幾點關門，回答「我想是五點半」。「Next to the pharmacy」答地點；「I posted it…」用 post 做同字陷阱。", src: "S2" },
  { q: "Is this seat taken?", opts: ["No, go right ahead.", "Yes, I took it yesterday.", "A window seat, please."], ans: 0, exp: "問「這個位子有人嗎」，回答「沒有，請坐」。「Yes, I took it yesterday」用 take 做同字陷阱，語意不通；「A window seat, please」是訂位用語。", src: "S2" },
  { q: "How did the product demonstration go?", opts: ["Better than we expected.", "It went to the Boston office.", "The product is sold online."], ans: 0, exp: "How did… go? 問進行得如何，回答「比預期好」。「It went to the Boston office」用 go／went 做同字陷阱；「The product is sold online」用 product 做同字陷阱。", src: "S2" },
  { q: "Who should I give these invoices to?", opts: ["Leave them on Gina's desk.", "Thirty dollars each.", "I gave a presentation yesterday."], ans: 0, exp: "Who 問要交給誰，間接回答「放在 Gina 的桌上」。「Thirty dollars each」答金額；「I gave a presentation」用 give 做同字陷阱。", src: "S2" },
  { q: "Aren't you presenting at the sales meeting?", opts: ["No, Patrick is doing it this time.", "The sales figures were strong.", "It meets every Monday."], ans: 0, exp: "否定疑問句問「你不是要在業務會議上報告嗎」，回答「不是，這次由 Patrick 報告」。另外兩個分別用 sales、meeting 做聯想，答非所問。", src: "S2" },
  { q: "Could you show me how to use the scanner?", opts: ["I'm in a meeting until three, actually.", "It scans both sides.", "Yes, I showed it to him and his whole team."], ans: 0, exp: "請對方教用掃描器，間接回答「其實我開會到三點」（現在沒空）。「It scans both sides」描述功能，沒回應請求；「I showed it to him」用 show 做同字陷阱。", src: "S2" },
  { q: "Do you know where the extra chairs are kept?", opts: ["Check the storage room downstairs.", "Yes, I'll keep it.", "Ten more people are coming."], ans: 0, exp: "問多的椅子放在哪裡，回答「去樓下儲藏室找」。「Yes, I'll keep it」用 keep 做同字陷阱；「Ten more people are coming」說的是人數。", src: "S2" },
  { q: "When will the shipment from Korea arrive?", opts: ["It's been delayed at customs.", "By air freight.", "Korea has great food."], ans: 0, exp: "When 問何時到，間接回答「在海關被耽擱了」。「By air freight」答運送方式；「Korea has great food」用 Korea 做聯想。", src: "S2" },
  { q: "Why is the parking lot so full today?", opts: ["There's a job fair in the lobby.", "Park on the second level.", "It's full of useful information."], ans: 0, exp: "Why 問停車場為什麼這麼滿，回答「大廳在辦徵才博覽會」。「Park on the second level」告訴對方停哪裡，沒回答原因；「It's full of useful information」用 full 做同字陷阱。", src: "S2" },
  { q: "Have the new uniforms been delivered?", opts: ["They're in the back room.", "Yes, the uniform size chart.", "Deliver them to the lobby."], ans: 0, exp: "問新制服送來了沒，間接回答「在後面的房間」（已經送到）。「Yes, the uniform size chart」答非所問；「Deliver them to the lobby」用 deliver 做同字陷阱，是指示而不是回答。", src: "S2" },
  { q: "Where's the nearest gas station?", opts: ["There's one just past the bridge.", "About forty dollars to fill up.", "Yes, it's nearly empty."], ans: 0, exp: "Where 問最近的加油站，回答「過橋就有一家」。「About forty dollars…」答加滿的費用；「Yes, it's nearly empty」用 Yes 回答 Where 問句。", src: "S2" },
  { q: "I can't find the contract you sent me.", opts: ["I'll e-mail it again.", "The contractor is here.", "The contract runs for two years."], ans: 0, exp: "對方說找不到合約，回應「我再寄一次」。「The contractor is here」用 contract／contractor 做相似字陷阱；「The contract runs for two years」描述合約內容，沒解決問題。", src: "S2" },
  { q: "How often do you back up the files?", opts: ["Every Friday afternoon.", "Back up the truck, please.", "In the cloud folder."], ans: 0, exp: "How often 問頻率，回答「每週五下午」。「Back up the truck」用 back up 做同字陷阱（備份／倒車）；「In the cloud folder」答地點。", src: "S2" },
  { q: "Would you rather meet on Tuesday or Wednesday?", opts: ["Either works for me.", "Yes, I'd rather not.", "The meeting went well."], ans: 0, exp: "選擇疑問句（週二還是週三），回答「哪天都可以」。選擇疑問句不能用 Yes 回答；「The meeting went well」用過去式描述會議，答非所問。", src: "S2" },
  { q: "Isn't the cafeteria closed on weekends?", opts: ["Only on Sundays.", "The café sells sandwiches.", "It's close to the station."], ans: 0, exp: "否定疑問句問「週末不是休息嗎」，回答「只有週日休息」。「The café sells sandwiches」用 café 聯想；「It's close to the station」用 close 做同字陷阱（關門／靠近）。", src: "S2" },
  { q: "Why did Ms. Duval leave early?", opts: ["She had a dentist appointment.", "Leave it on the table by the front entrance.", "Early in the morning."], ans: 0, exp: "Why 問提早離開的原因，回答「她要看牙醫」。「Leave it on the table」用 leave 做同字陷阱；「Early in the morning」用 early 做同字陷阱。", src: "S2" },
  { q: "Can I pay with a credit card?", opts: ["Yes, we accept all major cards.", "A birthday card for my sister.", "It costs twenty dollars."], ans: 0, exp: "問能不能刷卡，回答「可以，主要的卡都收」。「A birthday card…」用 card 做同字陷阱；「It costs twenty dollars」答價格。", src: "S2" },
  { q: "Who's in charge of the holiday party this year?", opts: ["The events committee is planning it.", "Last December.", "Charge it to my company account, please."], ans: 0, exp: "Who 問誰負責，回答「活動委員會在籌劃」。「Last December」答時間；「Charge it to my company account」用 charge 做同字陷阱。", src: "S2" },
  { q: "The quarterly report needs a few more changes.", opts: ["I'll revise it this afternoon.", "Change for a twenty, please.", "Every quarter."], ans: 0, exp: "對方說季報還要再改，回應「我今天下午修改」。「Change for a twenty」用 change 做同字陷阱（修改／零錢）；「Every quarter」用 quarterly 聯想，答非所問。", src: "S2" },
  { q: "Did you get the message I left?", opts: ["Sorry, my phone was off.", "The left side of the screen.", "A message board."], ans: 0, exp: "問有沒有收到留言，間接回答「抱歉，我手機關機了」（沒收到）。「The left side of the screen」用 left 做同字陷阱（留下／左邊）；「A message board」用 message 做同字陷阱。", src: "S2" },
  { q: "Which of these designs do you prefer?", opts: ["The blue one stands out more.", "A graphic designer.", "I prefer to work from home."], ans: 0, exp: "Which 問比較喜歡哪個設計，回答「藍色那個比較醒目」。「A graphic designer」用 design 聯想；「I prefer to work from home」用 prefer 做同字陷阱。", src: "S2" },
  { q: "How much does the annual membership cost?", opts: ["It depends on the plan you choose.", "Every year in June.", "A membership card."], ans: 0, exp: "How much 問費用，間接回答「要看你選哪個方案」。「Every year in June」答時間；「A membership card」用 membership 做同字陷阱。", src: "S2" },
  { q: "Where should we put the new printer?", opts: ["How about next to the copier?", "It prints in color.", "We bought it on sale last week from an online store."], ans: 0, exp: "Where 問印表機放哪裡，用反問提出建議「放在影印機旁邊如何？」。「It prints in color」描述功能；最後一個說的是在哪裡買的，答非所問。", src: "S2" },
  { q: "Let's order lunch for the whole team.", opts: ["Good idea — I'll get the menu.", "The team won the game.", "I ordered it online two weeks ago from the warehouse."], ans: 0, exp: "提議幫全隊訂午餐，回應「好主意，我去拿菜單」。「The team won the game」用 team 做同字陷阱；最後一個用 order 做同字陷阱，答非所問。", src: "S2" },
  { q: "Weren't the sales figures supposed to be ready by now?", opts: ["Accounting asked for one more day.", "Yes, they're for sale.", "Yes, the store's sale ends on Sunday afternoon."], ans: 0, exp: "否定疑問句問「銷售數字不是應該好了嗎」，間接回答「會計部要求再多一天」。另外兩個都用 sale 做同字陷阱，答非所問。", src: "S2" },
  { q: "Why don't you ask Mr. Kim for advice?", opts: ["He's out of the office this week.", "Because he gave me some advice.", "I asked for the bill and paid it at the front counter."], ans: 0, exp: "Why don't you…? 是建議，間接回答「他這週不在辦公室」（沒辦法問）。用 Because 回答建議是常見陷阱；最後一個用 ask 做同字陷阱，答非所問。", src: "S2" },
  { q: "When does your flight leave?", opts: ["Not until tomorrow night.", "From Gate 12, I believe.", "I'm flying with my two colleagues from the marketing department."], ans: 0, exp: "When 問班機何時起飛，回答「明天晚上才飛」。「From Gate 12」答登機門；最後一個答的是和誰同行。", src: "S2" },
  // ---- L1（2026-10-10）：完整聽力測驗第 1 回 Part 2，保留給完整測驗，不出現在一般練習 ----
  {"q": "Who's going to lead the training session on Monday?", "opts": ["Rachel volunteered, I believe.", "It starts at nine o'clock in Room B.", "The train leaves from platform four."], "ans": 0, "exp": "Who 問誰主持訓練，答「我記得是 Rachel 自願了」。「It starts at nine」答的是時間；「The train leaves…」用 training／train 的音近陷阱。", "src": "L1", "form": "L1"},
  {"q": "When will the renovations to the lobby be finished?", "opts": ["The contractor hasn't given us a date yet.", "Yes, the lobby looks brighter.", "On the first floor near the main entrance."], "ans": 0, "exp": "When 問何時完工，間接回答「承包商還沒給日期」。疑問詞問句不能用 Yes 回答；「On the first floor…」答的是地點。", "src": "L1", "form": "L1"},
  {"q": "Where did you put the signed contracts?", "opts": ["Ms. Tanaka took them to the legal department.", "I signed up for the workshop last week.", "Because the terms were revised."], "ans": 0, "exp": "Where 問合約放哪裡，答「Tanaka 女士拿去法務部了」。「I signed up…」用 sign 做同字陷阱；「Because…」答的是原因。", "src": "L1", "form": "L1"},
  {"q": "Why hasn't the shipment from Denver arrived yet?", "opts": ["There was a snowstorm on the highway.", "About two hundred boxes of paper.", "I'd like to ship it overnight, if possible."], "ans": 0, "exp": "Why 問貨為什麼還沒到，答「高速公路上有暴風雪」。「About two hundred boxes」答的是數量；「ship it overnight」用 shipment／ship 做同字根陷阱。", "src": "L1", "form": "L1"},
  {"q": "How often do you back up the client files?", "opts": ["Every night, automatically.", "Yes, I'll be right back after lunch.", "About three hundred clients."], "ans": 0, "exp": "How often 問頻率，答「每晚自動備份」。「I'll be right back」用 back 做同字陷阱，而且疑問詞問句不能用 Yes；「three hundred clients」答的是數量。", "src": "L1", "form": "L1"},
  {"q": "What did the board decide about the merger?", "opts": ["They're postponing the vote until next quarter.", "Yes, I was a little bored during it.", "On the top floor of the building."], "ans": 0, "exp": "What 問董事會的決定，答「他們把表決延到下一季」。「bored」和 board 同音陷阱；「On the top floor…」答的是地點。", "src": "L1", "form": "L1"},
  {"q": "Have you had a chance to review the budget proposal?", "opts": ["I'm just finishing it now.", "Yes, the view from the office is great.", "A fifty percent chance of rain."], "ans": 0, "exp": "問有沒有看過預算提案，答「我正在看完」。「the view…」用 review／view 的音近陷阱；「chance of rain」用 chance 做同字陷阱。", "src": "L1", "form": "L1"},
  {"q": "Is the cafeteria open on weekends?", "opts": ["Only on Saturday mornings.", "The salad bar was very popular.", "No, I'll open the window."], "ans": 0, "exp": "問餐廳週末有沒有開，答「只有週六上午」。「salad bar」只是相關聯想；「open the window」用 open 做同字陷阱。", "src": "L1", "form": "L1"},
  {"q": "Didn't Mr. Patel already approve the design?", "opts": ["He wants to see one more version first.", "A designer from Milan.", "I'd appreciate a reply by the end of the day on Friday."], "ans": 0, "exp": "否定問句確認 Patel 先生是否已核准設計，答「他想先再看一個版本」（＝還沒核准）。「A designer…」用 design／designer 做同字根陷阱；「I'd appreciate a reply…」和問題無關。", "src": "L1", "form": "L1"},
  {"q": "Aren't you presenting at the conference in Seoul?", "opts": ["My manager decided to go instead.", "It's a present for my colleague.", "It was in a big hall."], "ans": 0, "exp": "否定問句確認對方是否要在首爾的會議上簡報，答「我的主管決定改由他去」。「present」是同字不同義的陷阱（禮物）；「It was in a big hall」時態不合，而且答的是地點。", "src": "L1", "form": "L1"},
  {"q": "You've worked with this supplier before, haven't you?", "opts": ["Only on a couple of small orders.", "Supplies are kept in the cabinet by the door.", "No, the printer isn't working."], "ans": 0, "exp": "附加問句確認是否和這家供應商合作過，答「只合作過幾筆小訂單」。「Supplies」用 supplier／supplies 做同字根陷阱；「isn't working」用 work 做同字陷阱。", "src": "L1", "form": "L1"},
  {"q": "The quarterly report is due tomorrow, isn't it?", "opts": ["It's been pushed back to Friday.", "I reported it to the help desk this morning.", "Due to the heavy traffic."], "ans": 0, "exp": "附加問句確認報告是不是明天到期，答「已經延到週五了」。「reported」用 report 做同字陷阱；「Due to…」用 due 做同字不同義陷阱。", "src": "L1", "form": "L1"},
  {"q": "Would you rather meet in person or over video?", "opts": ["Whichever is easier for your team.", "Yes, I'd rather not.", "I watched the training video yesterday afternoon."], "ans": 0, "exp": "選擇疑問句，答「看你們團隊哪個方便」是常見的不直接選擇的正解。選擇疑問句不能用 Yes 回答；「watched the video」用 video 做同字陷阱。", "src": "L1", "form": "L1"},
  {"q": "Should we hire a caterer or order from the café downstairs?", "opts": ["The café's prices are more reasonable.", "We hired three new interns for the summer.", "The elevator downstairs is out of order today."], "ans": 0, "exp": "選擇疑問句，答「那家咖啡店的價格比較合理」，間接選擇咖啡店。「hired」用 hire 做同字陷阱；「The elevator downstairs…」只重複 downstairs，沒有回答要選哪一個。", "src": "L1", "form": "L1"},
  {"q": "The printer on the third floor is jammed again.", "opts": ["I'll call the technician right away.", "Please print twenty copies for the meeting.", "On the third floor of the annex."], "ans": 0, "exp": "陳述句說印表機又卡紙，回應「我馬上找技術人員」。「print」用 printer／print 做同字根陷阱；「On the third floor…」重複題目字詞。", "src": "L1", "form": "L1"},
  {"q": "I can't find the keys to the storage room.", "opts": ["Have you checked with the security desk?", "The key points of the presentation.", "We need more storage space."], "ans": 0, "exp": "陳述句說找不到儲藏室鑰匙，以問句回應「你問過保全櫃台了嗎？」。「key points」是同字不同義陷阱；「storage space」重複題目字詞。", "src": "L1", "form": "L1"},
  {"q": "Could you send me the agenda before the meeting?", "opts": ["I'll e-mail it to everyone this afternoon.", "The meeting went very well.", "She's a travel agent."], "ans": 0, "exp": "請求寄議程，答「我今天下午會寄給大家」。「The meeting went very well」時態不合；「agent」和 agenda 的音近陷阱。", "src": "L1", "form": "L1"},
  {"q": "Why don't I drive you to the airport tomorrow?", "opts": ["Thanks, but I've already booked a taxi.", "Because the flight was delayed by two hours.", "The airport is being expanded this year to add a terminal."], "ans": 0, "exp": "Why don't I… 是主動提議（我載你去機場吧），答「謝謝，但我已經叫了計程車」。「Because…」把提議誤當成問原因；「The airport is being expanded」只重複 airport。", "src": "L1", "form": "L1"},
  {"q": "How much will it cost to repair the air conditioner?", "opts": ["It might be cheaper to replace it.", "It's been unusually cold all week, hasn't it?", "Twenty degrees, I think."], "ans": 0, "exp": "How much 問修冷氣的費用，間接回答「換新的可能比較便宜」（暗示修理很貴）。「cold」「Twenty degrees」都是由冷氣聯想的陷阱。", "src": "L1", "form": "L1"},
  {"q": "Which hotel are the clients staying at?", "opts": ["Let me check their itinerary.", "For three nights.", "Yes, they're staying for lunch."], "ans": 0, "exp": "Which 問客戶住哪家飯店，答「我查一下他們的行程表」。「For three nights」答的是住多久；疑問詞問句不能用 Yes，而且 staying 是同字陷阱。", "src": "L1", "form": "L1"},
  {"q": "Where's the nearest place to buy stamps?", "opts": ["There's a post office across the street.", "Stamp it with the official company seal, please.", "About fifty cents each, or a dollar for international mail."], "ans": 0, "exp": "Where 問哪裡買郵票，答「對街有郵局」。「Stamp it…」是同字不同義（蓋章）；「fifty cents each」答的是價格。", "src": "L1", "form": "L1"},
  {"q": "Who approved the overtime for the weekend shift?", "opts": ["Nobody has, as far as I know.", "Over the weekend, mostly.", "The night shift starts at six in the evening."], "ans": 0, "exp": "Who 問誰核准加班，答「據我所知還沒有人核准」。「Over the weekend」重複題目字詞；「The shift starts at six」答的是時間。", "src": "L1", "form": "L1"},
  {"q": "Do you know if the new software is compatible with our system?", "opts": ["The IT team is testing it now.", "No, I haven't met him yet.", "It comes in a larger box."], "ans": 0, "exp": "問新軟體和系統是否相容，答「IT 團隊正在測試」（＝還不知道，正在確認）。「I haven't met him」把 know 誤解成認識某人；「a larger box」和相容性無關。", "src": "L1", "form": "L1"},
  {"q": "The client wants the samples by Thursday.", "opts": ["That doesn't give us much time.", "Several free samples were handed out at the fair.", "On Thursday evenings."], "ans": 0, "exp": "陳述客戶週四前要樣品，回應「那我們時間不多」。「free samples」重複 samples；「On Thursday evenings」重複 Thursday。", "src": "L1", "form": "L1"},
  {"q": "When is the new branch manager starting?", "opts": ["Hasn't the announcement been made yet?", "At the main branch downtown, near the station.", "He managed the old branch quite well, I heard."], "ans": 0, "exp": "When 問新分行經理何時上任，以反問回應「公告還沒發嗎？」。「At the main branch」答的是地點；「managed」用 manager／manage 做同字根陷阱。", "src": "L1", "form": "L1"},
  // ---- L1（2026-10-10）：完整聽力測驗第 1 回 Part 2，保留給完整測驗，不出現在一般練習 ----
  {"q": "Who's in charge of ordering new office chairs?", "opts": ["That would be Linda in facilities.", "They're very comfortable, thank you.", "Please have a seat in the lobby."], "ans": 0, "exp": "Who 問誰負責訂椅子，答「設施部的 Linda」。「They're very comfortable」只是由椅子聯想；「have a seat」用 chair／seat 做相關字陷阱。", "src": "L2", "form": "L2"},
  {"q": "When does the new parking policy take effect?", "opts": ["At the start of next month.", "Yes, the policy was updated recently by management.", "In the garage behind the building."], "ans": 0, "exp": "When 問何時生效，答「下個月初」。疑問詞問句不能用 Yes；「In the garage…」答的是地點。", "src": "L2", "form": "L2"},
  {"q": "Where can I find the updated price list?", "opts": ["It's been posted on the shared drive.", "Prices have gone up again.", "I found it very useful, thanks."], "ans": 0, "exp": "Where 問哪裡找價目表，答「放在共用雲端硬碟」。「Prices have gone up」由 price 聯想；「I found it…」用 find／found 做同字陷阱。", "src": "L2", "form": "L2"},
  {"q": "Why was the board meeting moved to the afternoon?", "opts": ["Several directors had morning flights.", "In the boardroom on the tenth floor.", "Thanks, I moved into a new apartment recently."], "ans": 0, "exp": "Why 問會議為何改到下午，答「幾位董事早上要搭飛機」。「In the boardroom…」答的是地點；「I moved into…」用 moved 做同字陷阱。", "src": "L2", "form": "L2"},
  {"q": "How long will the system upgrade take?", "opts": ["Most of the day, unfortunately.", "It's a very long hallway.", "Yes, the upgrade is free for all current customers."], "ans": 0, "exp": "How long 問需要多久，答「恐怕要大半天」。「a very long hallway」用 long 做同字陷阱；疑問詞問句不能用 Yes。", "src": "L2", "form": "L2"},
  {"q": "Which supplier did we choose for the packaging?", "opts": ["We're still comparing the last two bids.", "Please choose any seat you like.", "The boxes arrived damaged."], "ans": 0, "exp": "Which 問選了哪家供應商，間接回答「還在比較最後兩家的報價」。「choose any seat」用 choose 做同字陷阱；「The boxes arrived damaged」只是由 packaging 聯想。", "src": "L2", "form": "L2"},
  {"q": "What time does the client's train get in?", "opts": ["Around four, if it's on schedule.", "The training starts on Monday morning.", "Please come in and have a seat."], "ans": 0, "exp": "What time 問火車幾點到，答「準點的話大約四點」。「training」和 train 是同字根陷阱；「come in」用 in 做同字陷阱。", "src": "L2", "form": "L2"},
  {"q": "Has the marketing budget been approved yet?", "opts": ["The finance team needs one more day.", "It was a very successful marketing campaign last year.", "No, I haven't been there."], "ans": 0, "exp": "問預算核准了沒，答「財務部還需要一天」（＝還沒）。「successful marketing campaign」重複 marketing；「I haven't been there」答非所問。", "src": "L2", "form": "L2"},
  {"q": "Are you going to the trade show in Frankfurt?", "opts": ["Only if my travel request is approved.", "The show starts at eight.", "Yes, I've traded in my old car."], "ans": 0, "exp": "問是否去法蘭克福商展，答「出差申請核准才會去」。「The show starts at eight」答時間；「traded in」用 trade 做同字陷阱。", "src": "L2", "form": "L2"},
  {"q": "Did you remember to lock the storage room?", "opts": ["Marco was the last one to leave.", "I don't remember his name.", "There's more room in the back."], "ans": 0, "exp": "問有沒有鎖儲藏室，間接回答「Marco 是最後離開的人」（暗示由他負責）。「I don't remember his name」用 remember 做同字陷阱；「more room」用 room 做同字不同義陷阱。", "src": "L2", "form": "L2"},
  {"q": "Isn't the cafeteria closed for renovations this week?", "opts": ["It reopened yesterday, actually.", "The menu changes every day.", "I'd like a table near the window, please."], "ans": 0, "exp": "否定問句確認餐廳是否在整修，答「其實昨天已經重新開放」。另外兩個只是由餐廳聯想，沒有回答問題。", "src": "L2", "form": "L2"},
  {"q": "Shouldn't we print more copies of the agenda?", "opts": ["Fifty should be plenty.", "The printer is next to the copier.", "I agree with most of the items on it."], "ans": 0, "exp": "否定問句建議多印議程，答「五十份應該夠了」（＝不用再印）。「The printer is next to the copier」由印刷聯想；「I agree with most of the items」由 agenda 聯想。", "src": "L2", "form": "L2"},
  {"q": "You've already signed the lease, haven't you?", "opts": ["The landlord is reviewing a few changes.", "Please sign at the bottom of the form.", "Yes, the sign is easy to see from the road."], "ans": 0, "exp": "附加問句確認是否已簽租約，答「房東在看幾處修改」（＝還沒簽）。「sign at the bottom」用 sign 做同字陷阱；「the sign is easy to see」是同字不同義（招牌）。", "src": "L2", "form": "L2"},
  {"q": "The conference room projector isn't working, is it?", "opts": ["I'll ask IT to take a look.", "It's a big project for our team.", "No, I usually work from home on Fridays."], "ans": 0, "exp": "附加問句確認投影機是不是壞了，回應「我請 IT 來看看」。「project」和 projector 音近；「work from home」用 work 做同字陷阱。", "src": "L2", "form": "L2"},
  {"q": "Would you like the report printed or sent by e-mail?", "opts": ["An electronic copy is fine.", "Yes, I'd like that very much.", "The printer on the second floor."], "ans": 0, "exp": "選擇疑問句，答「電子檔就好」＝選 e-mail。選擇疑問句通常不用 Yes 回答；「The printer…」答的是地點。", "src": "L2", "form": "L2"},
  {"q": "Is the workshop on Tuesday or Wednesday?", "opts": ["It's been moved to Thursday.", "Yes, every Tuesday at noon.", "I'll work in the shop this weekend."], "ans": 0, "exp": "選擇疑問句問週二或週三，答「已改到週四」，兩個都不是，是常見的正解型態。「Yes, every Tuesday」用 Yes 回答選擇題；「work in the shop」用 workshop 拆字做陷阱。", "src": "L2", "form": "L2"},
  {"q": "I think the heater in the lobby is broken.", "opts": ["Let's put in a repair request.", "It's been broken into three groups.", "The lobby opens at seven."], "ans": 0, "exp": "陳述句說大廳暖氣壞了，回應「我們提報修單吧」。「broken into three groups」是同字不同義（分成）；「The lobby opens at seven」重複 lobby。", "src": "L2", "form": "L2"},
  {"q": "The client just canceled tomorrow's meeting.", "opts": ["Did they say why?", "I'll meet you at the station.", "Tomorrow is supposed to be sunny."], "ans": 0, "exp": "陳述客戶取消會議，以問句回應「他們有說原因嗎？」。「meet you」用 meeting／meet 做同字根陷阱；「Tomorrow is supposed to be sunny」只重複 tomorrow。", "src": "L2", "form": "L2"},
  {"q": "Could you help me set up the chairs for the seminar?", "opts": ["Sure, how many rows do you need?", "The seminar was very informative.", "She's the chair of the committee."], "ans": 0, "exp": "請求幫忙排椅子，答「好啊，要排幾排？」。「The seminar was very informative」時態不合；「chair of the committee」是同字不同義（主席）。", "src": "L2", "form": "L2"},
  {"q": "Why don't we take a short break?", "opts": ["Good idea, I could use some coffee.", "Because the window was broken.", "It's a short walk from here."], "ans": 0, "exp": "Why don't we 是提議（休息一下吧），答「好主意，我正想喝杯咖啡」。「Because…」把提議誤當成問原因；「broken」和 break 是同字根陷阱；「a short walk」重複 short。", "src": "L2", "form": "L2"},
  {"q": "How much does it cost to ship this package overseas?", "opts": ["That depends on how much it weighs.", "About two weeks by regular mail.", "Yes, the ship leaves on Friday."], "ans": 0, "exp": "How much 問運費，答「要看重量」，是常見的間接回答。「About two weeks」答的是時間；「the ship leaves」是同字不同義（船）。", "src": "L2", "form": "L2"},
  {"q": "Who's going to replace Ms. Ortiz while she's on leave?", "opts": ["Her assistant will handle most of her accounts.", "She's leaving at five today.", "In place of the old one."], "ans": 0, "exp": "Who 問誰代理 Ortiz 女士的工作，答「她的助理會處理大部分客戶」。「She's leaving at five」把 on leave（休假）誤當成 leave（離開）；「In place of the old one」由 replace 聯想。", "src": "L2", "form": "L2"},
  {"q": "Where should we hold the welcome reception?", "opts": ["The garden would be nice if it doesn't rain.", "Please hold the elevator for me.", "Around one hundred guests."], "ans": 0, "exp": "Where 問迎新酒會辦在哪，答「不下雨的話花園不錯」。「hold the elevator」是同字不同義；「one hundred guests」答的是人數。", "src": "L2", "form": "L2"},
  {"q": "Do you know when the inspection is scheduled?", "opts": ["I'll check the calendar for you.", "Yes, I know him very well.", "The inspector found no problems at the factory last year."], "ans": 0, "exp": "問檢查排在什麼時候，答「我幫你查一下行事曆」。「I know him very well」把 know 誤解成認識某人；「inspector found no problems」用 inspection／inspector 做同字根陷阱，而且時態不合。", "src": "L2", "form": "L2"},
  {"q": "When are the new laptops being delivered?", "opts": ["Didn't you get the e-mail from purchasing?", "On the desk next to the window.", "They're much lighter than the old ones we used."], "ans": 0, "exp": "When 問新筆電何時送到，以反問回應「你沒收到採購部的信嗎？」（暗示信裡有寫）。「On the desk…」答的是地點；「much lighter」只是由筆電聯想。", "src": "L2", "form": "L2"},
  // ---- C1：練習題批次 ----
  {"q": "Who's covering the front desk during lunch today?", "opts": ["Hiro said he'd take the first hour.", "The desk lamp needs a new bulb.", "At the Italian place across the street."], "ans": 0, "sk": "l2-wh", "exp": "Who 問今天午餐時間誰顧櫃檯，答「Hiro 說他會顧第一個小時」。「The desk lamp…」用 desk 做同字陷阱；「At the Italian place…」由 lunch 聯想到去哪裡吃飯，答的是地點，不是人。", "src": "C1"},
  {"q": "Who designed the new company logo?", "opts": ["Wasn't it an outside agency?", "Yes, it looks much more modern.", "I'm taking a design course this fall."], "ans": 0, "sk": "l2-wh", "exp": "Who 問誰設計了新標誌，用反問「不是外面的廣告公司做的嗎？」間接回答，這是高分常見的正解型態。「Yes, it looks…」疑問詞問句不能用 Yes 回答；「design course」用 design 做同字陷阱。", "src": "C1"},
  {"q": "Who's giving the keynote speech at the retail summit?", "opts": ["The lineup isn't final yet.", "That's a key point in the report.", "About forty minutes, I believe."], "ans": 0, "sk": "l2-wh", "exp": "Who 問誰在零售高峰會做主題演講（keynote speech），間接回答「講者名單還沒定案」。「key point」和 keynote 發音相近，是音近陷阱；「About forty minutes」答的是多久，不是誰。", "src": "C1"},
  {"q": "What did you think of the new intern's presentation?", "opts": ["She explained the data very clearly.", "I think it starts at two.", "The internship lasts three months."], "ans": 0, "sk": "l2-wh", "exp": "What did you think 問對實習生簡報的看法，答「她把數據講解得很清楚」。「I think it starts at two」重複 think，而且答的是時間；「The internship lasts…」由 intern 聯想，沒有評價簡報。", "src": "C1"},
  {"q": "What's the fastest way to get to the convention center?", "opts": ["The subway, at this time of day.", "The convention opens on Friday morning.", "Yes, I got there early this time."], "ans": 0, "sk": "l2-wh", "exp": "What's the fastest way 問最快的去法，答「這個時段搭地鐵最快」。「The convention opens on Friday」答的是何時；「Yes, I got there early」疑問詞問句不能用 Yes 回答，get there 也只是同字重複。", "src": "C1"},
  {"q": "What's the dress code for the client dinner?", "opts": ["Let me check the invitation.", "The code is printed on your badge.", "At seven, at the Harbor Grill."], "ans": 0, "sk": "l2-wh", "exp": "What 問客戶晚宴的服裝規定（dress code），間接回答「我查一下邀請函」。「The code is printed…」的 code 是「代碼」，同字不同義；「At seven, at the Harbor Grill」答的是時間和地點。", "src": "C1"},
  {"q": "What's causing the delay on the production line?", "opts": ["One of the machines overheated.", "Please wait in line right here, sir.", "Production rose last year."], "ans": 0, "sk": "l2-wh", "exp": "What's causing 問生產線延誤的原因，答「有一台機器過熱」。「wait in line」的 line 是「隊伍」，同字不同義；「Production rose last year」重複 production，但沒說延誤原因。", "src": "C1"},
  {"q": "When is the deadline for the grant application?", "opts": ["The end of this month, I think.", "Please apply the stickers to each box.", "It's a fairly long form."], "ans": 0, "sk": "l2-wh", "exp": "When 問補助金（grant）申請截止日，答「我想是這個月底」。「apply the stickers」的 apply 是「貼上」，和 application 同字根但意思不同；「It's a fairly long form」只是由申請表聯想，沒說時間。", "src": "C1"},
  {"q": "When are you taking your vacation this year?", "opts": ["That depends on the project schedule.", "To Portugal, with my sister.", "Yes, I took the whole week off."], "ans": 0, "sk": "l2-wh", "exp": "When 問今年何時休假，間接回答「要看專案進度而定」。「To Portugal…」答的是去哪裡；「Yes, I took…」疑問詞問句不能用 Yes 回答，而且用過去式，和問未來的休假對不上。", "src": "C1"},
  {"q": "When should we send out the customer newsletter?", "opts": ["Right after the product announcement.", "Yes, the news was surprising.", "To everyone on our customer mailing list."], "ans": 0, "sk": "l2-wh", "exp": "When 問電子報何時寄出，答「產品發表之後馬上寄」。「Yes, the news…」用 Yes 回答疑問詞問句，news 和 newsletter 是拆字陷阱；「To everyone on our customer mailing list」答的是寄給誰，不是何時。", "src": "C1"},
  {"q": "Where did you get that standing desk?", "opts": ["A shop near my place.", "I prefer to stand during calls.", "It adjusts to almost any height."], "ans": 0, "sk": "l2-wh", "exp": "Where 問那張站立式書桌在哪裡買的，答「我家附近的一家店」。「I prefer to stand…」用 stand 做同字陷阱；「It adjusts to almost any height」由站立式書桌聯想到功能，沒回答在哪裡買。", "src": "C1"},
  {"q": "Where are we meeting the investors on Monday?", "opts": ["Their assistant is still booking a place.", "At ten, before lunch.", "They've invested in two startups."], "ans": 0, "sk": "l2-wh", "exp": "Where 問週一在哪裡和投資人見面，間接回答「他們的助理還在訂地點」。「At ten, before lunch」答的是時間；「invested」和 investors 同字根，是相關字陷阱。", "src": "C1"},
  {"q": "Where do I drop off the rental car?", "opts": ["In the lot across from Terminal B.", "It's a compact car.", "Sure, I'll drop by later."], "ans": 0, "sk": "l2-wh", "exp": "Where 問租來的車在哪裡還，答「B 航廈對面的停車場」。「It's a compact car」只是由 car 聯想到車型；「drop by」（順道過去）和 drop off 同字不同義。", "src": "C1"},
  {"q": "Why did the bank call you this morning?", "opts": ["To confirm a recent payment.", "Shortly after nine thirty.", "I'll call you back this afternoon."], "ans": 0, "sk": "l2-wh", "exp": "Why 問銀行今早為什麼打電話來，答「要確認最近的一筆付款」，用 To 不定詞表示目的。「Shortly after nine thirty」答的是何時；「I'll call you back…」用 call 做同字陷阱。", "src": "C1"},
  {"q": "Why is Ines working from home this week?", "opts": ["She's waiting for some furniture deliveries.", "She works on the design team.", "Mostly on Tuesdays and Thursdays."], "ans": 0, "sk": "l2-wh", "exp": "Why 問 Ines 這週為什麼在家工作，答「她在等家具送貨」。「She works on the design team」重複 work，但說的是她在哪個部門；「Mostly on Tuesdays…」答的是哪幾天，不是原因。", "src": "C1"},
  {"q": "Why did the restaurant change its menu?", "opts": ["The new chef wanted lighter dishes.", "I'll have the soup of the day, please.", "It opens at eleven every weekday morning."], "ans": 0, "sk": "l2-wh", "exp": "Why 問餐廳為什麼換菜單，答「新主廚想做比較清淡的菜」。「I'll have the soup…」是點餐用語，只由 menu 聯想；「It opens at eleven…」答的是營業時間。", "src": "C1"},
  {"q": "How did you hear about this position?", "opts": ["A former colleague recommended it.", "The position is full-time.", "I can hear you much more clearly now."], "ans": 0, "sk": "l2-wh", "exp": "How did you hear 問（面試時）怎麼得知這個職缺，答「以前的同事推薦的」。「The position is full-time」重複 position 但沒回答管道；「I can hear you much more clearly」的 hear 是「聽得到聲音」，同字不同義。", "src": "C1"},
  {"q": "How many welcome kits should we order for the seminar?", "opts": ["Let's wait until registration closes.", "The kitchen's on the left.", "It was a helpful seminar."], "ans": 0, "sk": "l2-wh", "exp": "How many 問研討會要訂幾份迎賓包，間接回答「等報名截止再說」（到時才知道人數）。「kitchen」和 kit 發音相近；「It was a helpful seminar」用過去式評論研討會，答非所問。", "src": "C1"},
  {"q": "How much time should I set aside for the interview?", "opts": ["About an hour should do.", "Just set it aside on my desk.", "The interviewer seemed very friendly."], "ans": 0, "sk": "l2-wh", "exp": "How much time 問面試要預留多少時間（set aside），答「大約一小時就夠了」。「set it aside on my desk」的 set aside 是「放在旁邊」，同字不同義；「The interviewer seemed…」由 interview 聯想到面試官。", "src": "C1"},
  {"q": "How do you like working at the new site?", "opts": ["The commute is much easier.", "I'd like a large one, please.", "Check the company website."], "ans": 0, "sk": "l2-wh", "exp": "How do you like 問對新工作地點的感想，答「通勤方便多了」。「I'd like a large one」用 like 做同字陷阱（意思是「想要」）；「website」和 site 是拆字音近陷阱。", "src": "C1"},
  {"q": "Which train should I take to the Westfield office?", "opts": ["Any of the express lines will do.", "I'll take notes for you.", "The office closes at six."], "ans": 0, "sk": "l2-wh", "exp": "Which 問去 Westfield 辦公室該搭哪班車，答「任何一條快線都可以」。「take notes」用 take 做同字陷阱；「The office closes at six」重複 office，答的是時間。", "src": "C1"},
  {"q": "Which of the candidates impressed you the most?", "opts": ["Ms. Nakamura, without a doubt.", "It was an impressive building.", "Mostly for sales positions."], "ans": 0, "sk": "l2-wh", "exp": "Which of the candidates 問哪位應徵者最讓人印象深刻，答「毫無疑問是 Nakamura 小姐」。「impressive building」用 impress 的同字根做陷阱；「Mostly for sales positions」由應徵者聯想到職缺，沒指出是哪一位。", "src": "C1"},
  {"q": "Have you tried the new scheduling app yet?", "opts": ["Not yet, but I've heard good things.", "I'll try to be there by noon.", "The schedule was posted on Monday morning."], "ans": 0, "sk": "l2-yn", "exp": "問用過新的排程 App 沒，答「還沒，但聽說不錯」。「I'll try to be there」的 try 是「盡量」，同字不同義；「The schedule was posted…」由 scheduling 聯想到班表，答非所問。", "src": "C1"},
  {"q": "Is the gym on the ground floor open to all employees?", "opts": ["Only if you register first.", "I opened a new account there.", "Yes, the floor was just mopped."], "ans": 0, "sk": "l2-yn", "exp": "問一樓健身房是否開放給全體員工，答「要先登記才可以」。「I opened a new account」用 open 做同字陷阱；「Yes, the floor was just mopped」雖然有 Yes，但說的是地板剛拖過，用 floor 做同字陷阱。", "src": "C1"},
  {"q": "Did the courier come by for the legal documents?", "opts": ["The package is still at reception.", "He's a lawyer, actually.", "Yes, the documentary was great."], "ans": 0, "sk": "l2-yn", "exp": "問快遞有沒有來收法律文件，間接回答「包裹還在櫃檯」（＝還沒來收）。「He's a lawyer」由 legal 聯想到律師；「documentary」（紀錄片）和 documents 發音相近，是音近陷阱。", "src": "C1"},
  {"q": "Will the store be open on the national holiday?", "opts": ["Only until three that afternoon.", "I stored them in the basement.", "We had a wonderful holiday in Spain."], "ans": 0, "sk": "l2-yn", "exp": "問國定假日店有沒有開，答「只開到那天下午三點」（＝有開，但時間縮短）。「stored」是動詞「存放」，和 store（商店）同字不同義；「We had a wonderful holiday」用過去式談假期，答非所問。", "src": "C1"},
  {"q": "Didn't you use to work in the Lisbon office?", "opts": ["Yes, for about two years.", "The office is closed on Fridays.", "It works perfectly now."], "ans": 0, "sk": "l2-yn", "exp": "否定問句確認對方以前是否在里斯本辦公室工作，答「對，大約兩年」。「The office is closed…」重複 office 但沒回答；「It works perfectly」的 work 是「運作」，同字不同義。", "src": "C1"},
  {"q": "Isn't Mr. Fischer retiring at the end of the year?", "opts": ["He's changed his mind, apparently.", "The tire needs replacing.", "At the end of the hallway."], "ans": 0, "sk": "l2-yn", "exp": "否定問句確認 Fischer 先生是否年底退休，間接回答「聽說他改變心意了」（＝不退休了）。「tire」和 retiring 的後半發音相近；「At the end of the hallway」重複 the end of，答的是地點。", "src": "C1"},
  {"q": "Shouldn't the caterers be here by now?", "opts": ["They're parking now.", "I've been here since nine.", "Here's the menu we chose."], "ans": 0, "sk": "l2-yn", "exp": "否定問句表示外燴人員早該到了，答「他們正在停車」（＝已經到了）。「I've been here since nine」重複 here，說的是自己；「Here's the menu we chose」由外燴聯想到菜單，沒回答是否到了。", "src": "C1"},
  {"q": "The new hires start orientation tomorrow, don't they?", "opts": ["HR is still finalizing the schedule.", "The higher floors are quieter.", "I hired a moving company."], "ans": 0, "sk": "l2-yn", "exp": "附加問句確認新進員工（new hires）是否明天開始新人訓練，間接回答「人資還在敲定時程」（＝還不確定）。「higher」和 hires 發音相近；「hired a moving company」的 hire 是「雇用搬家公司」，同字不同情境。", "src": "C1"},
  {"q": "You haven't seen my reading glasses, have you?", "opts": ["Did you check the conference room?", "Yes, I read it last night.", "A glass of water, please."], "ans": 0, "sk": "l2-yn", "exp": "附加問句問有沒有看到自己的老花眼鏡，用反問「你找過會議室了嗎？」間接回答（暗示可能放在那裡）。「I read it last night」用 read 做同字陷阱；「A glass of water」的 glass 是「玻璃杯」，同字不同義。", "src": "C1"},
  {"q": "This bus goes to the art museum, right?", "opts": ["Yes, it stops right out front.", "The art supplies are in the closet.", "The exhibit opens in May."], "ans": 0, "sk": "l2-yn", "exp": "附加問句（…, right?）確認這班公車是否到美術館，答「對，就停在正門口」。「art supplies」用 art 做同字陷阱；「The exhibit opens in May」由 museum 聯想到展覽，沒回答公車路線。", "src": "C1"},
  {"q": "Has IT installed the new firewall yet?", "opts": ["They're doing it this weekend.", "The fire drill is at ten o'clock.", "It's a very well-run department."], "ans": 0, "sk": "l2-yn", "exp": "問資訊部裝好新的防火牆（firewall）了沒，答「他們週末會裝」（＝還沒）。「fire drill」（消防演習）用 fire 做拆字陷阱；「It's a very well-run department」由 IT 聯想到部門，答非所問。", "src": "C1"},
  {"q": "Do you know if Ms. Reyes accepted the job offer?", "opts": ["She asked for a few more days.", "She offered me a ride home.", "Yes, I know the job well."], "ans": 0, "sk": "l2-yn", "exp": "間接問句問 Reyes 小姐有沒有接受工作邀約，間接回答「她要求再多給幾天」（＝還沒決定）。「offered me a ride」用 offer 做同字陷阱；「Yes, I know the job well」重複 know 和 job，但回答的是自己熟不熟悉這份工作。", "src": "C1"},
  {"q": "Should we hold the retreat in the mountains or by the coast?", "opts": ["The coast is easier to reach.", "Yes, I'd love to go there sometime.", "Hold on, let me grab a pen first."], "ans": 0, "sk": "l2-choice", "exp": "選擇問句問員工旅遊辦在山上還是海邊，答「海邊比較好到達」＝選海邊。選擇問句不能用 Yes 回答；「Hold on」（等一下）用 hold 做同字陷阱。", "src": "C1"},
  {"q": "Do you want to pay now or when you pick up the order?", "opts": ["I'll pay at pickup, thanks.", "Yes, I paid it in full last week.", "Pick any color you like."], "ans": 0, "sk": "l2-choice", "exp": "選擇問句問現在付款還是取貨時付，答「取貨時再付」。「Yes, I paid it in full last week」用 Yes 回答選擇問句，時態也不對；「Pick any color」的 pick 是「挑選」，和 pick up 同字不同義。", "src": "C1"},
  {"q": "Are you taking the early flight or the one at noon?", "opts": ["I'm actually driving down.", "It's about a two-hour flight.", "Yes, I'll take it."], "ans": 0, "sk": "l2-choice", "exp": "選擇問句問搭早班還是中午的班機，答「其實我要開車去」，兩個都不選，是常見的高分正解型態。「It's about a two-hour flight」答的是飛多久；「Yes, I'll take it」用 Yes 回答選擇問句。", "src": "C1"},
  {"q": "Would you rather review the contract yourself, or should I send it to legal?", "opts": ["Legal should probably see it first.", "It's a two-year contract.", "The view from here is great."], "ans": 0, "sk": "l2-choice", "exp": "選擇問句問要自己看合約，還是送法務部，答「最好先給法務看」＝選送法務。「It's a two-year contract」重複 contract 但沒做選擇；「view」和 review 是拆字音近陷阱。", "src": "C1"},
  {"q": "Should I print the name badges, or is the venue making them?", "opts": ["The venue said they'd handle them.", "My name is spelled with a K, not a C.", "About one hundred and twenty."], "ans": 0, "sk": "l2-choice", "exp": "選擇問句問名牌要自己印還是場地方製作，答「場地方說他們會處理」＝選場地方。「My name is spelled…」用 name 做同字陷阱；「About one hundred and twenty」答的是數量。", "src": "C1"},
  {"q": "Should we repaint the office or just replace the carpet?", "opts": ["Let's see what the budget allows.", "I painted my kitchen last month, too.", "Yes, it's such a lovely, bright office."], "ans": 0, "sk": "l2-choice", "exp": "選擇問句問辦公室要重新粉刷還是只換地毯，間接回答「看預算允許做到哪裡」。「I painted my kitchen」用 paint 做同字陷阱；「Yes, it's such a lovely, bright office」用 Yes 回答選擇問句。", "src": "C1"},
  {"q": "Did Mr. Haddad want the window table or the private room?", "opts": ["He didn't specify, actually.", "The window by the door won't open.", "I'll set the table for them now."], "ans": 0, "sk": "l2-choice", "exp": "選擇問句問 Haddad 先生要靠窗的桌子還是包廂，間接回答「他其實沒特別說」。「The window by the door won't open」用 window 做同字陷阱；「I'll set the table for them」用 table 做同字陷阱（擺餐具）。", "src": "C1"},
  {"q": "Will you take the job in Toronto or stay here?", "opts": ["I'm still weighing the offer.", "It takes about an hour by train.", "Yes, I'll stay for dinner tonight."], "ans": 0, "sk": "l2-choice", "exp": "選擇問句問要接多倫多的工作還是留下，間接回答「我還在考慮那個工作邀約」（weigh＝衡量）。「It takes about an hour」用 take 做同字陷阱；「Yes, I'll stay for dinner」用 Yes 回答，stay 也是同字不同情境。", "src": "C1"},
  {"q": "Could you take notes during the client call?", "opts": ["Sure, I'll bring my laptop.", "I took the call at noon.", "Please leave a note on my desk."], "ans": 0, "sk": "l2-req", "exp": "請求對方在客戶電話會議時做筆記，答「好，我帶筆電去」＝答應。「I took the call at noon」用 take／call 做同字陷阱；「leave a note」用 note 做同字陷阱（留字條），反過來要求對方。", "src": "C1"},
  {"q": "Would you mind turning the music down a little?", "opts": ["Sorry, I didn't realize it was loud.", "The music store closes at eight.", "Turn left at the next corner."], "ans": 0, "sk": "l2-req", "exp": "Would you mind 請對方把音樂調小聲，答「抱歉，我沒發現這麼大聲」＝會調小。「The music store…」用 music 做同字陷阱；「Turn left…」用 turn 做同字陷阱（轉彎）。", "src": "C1"},
  {"q": "Do you want me to proofread the proposal before it goes out?", "opts": ["Ravi already checked it, thanks.", "I proposed the idea last week.", "It went out of business."], "ans": 0, "sk": "l2-req", "exp": "提議幫忙校對（proofread）提案，間接婉拒「Ravi 已經看過了，謝謝」。「proposed」和 proposal 同字根；「went out of business」（倒閉）用 go out 做同字不同義陷阱。", "src": "C1"},
  {"q": "Why don't I set up the video call for you?", "opts": ["Thanks, I'm not great with that software.", "Because the camera was broken.", "I called you twice yesterday."], "ans": 0, "sk": "l2-req", "exp": "Why don't I… 是提議幫忙設定視訊會議，不是問原因；答「謝謝，我不太會用那個軟體」＝接受。「Because…」把提議誤當成問原因，camera 也只是相關字聯想；「I called you twice」用 call 做同字陷阱。", "src": "C1"},
  {"q": "Would you like to join our book club?", "opts": ["When does it meet?", "I booked a table for six.", "It's a very long novel."], "ans": 0, "sk": "l2-req", "exp": "邀請對方加入讀書會，用反問「什麼時候聚會？」間接回應（先問時間再決定）。「booked」（預訂）和 book（書）同字不同義；「It's a very long novel」只是由讀書會聯想到小說，沒回應邀請。", "src": "C1"},
  {"q": "We're having a farewell lunch for Akiko on Friday. Can you come?", "opts": ["I'll be at a client site, unfortunately.", "The lunch menu changes daily.", "Friday's forecast looks sunny."], "ans": 0, "sk": "l2-req", "exp": "邀請對方週五參加 Akiko 的歡送午餐，答「很可惜，我那天要去客戶那裡」＝婉拒。「The lunch menu…」重複 lunch 但沒回應邀請；「Friday's forecast…」重複 Friday，說的是天氣。", "src": "C1"},
  {"q": "Let's ask the vendor for a discount.", "opts": ["It's worth a try.", "We counted them twice.", "The vendor's booth is near the exit."], "ans": 0, "sk": "l2-req", "exp": "Let's 提議向廠商要折扣，答「值得試試看」＝贊成。「counted」和 discount 的後半發音相近；「The vendor's booth…」重複 vendor，說的是攤位位置。", "src": "C1"},
  {"q": "How about moving the team meeting to the morning?", "opts": ["Half the team is in training then.", "Good morning to you, too.", "It meets in Room Four."], "ans": 0, "sk": "l2-req", "exp": "How about 提議把團隊會議改到早上，間接回應「那時候一半的人在受訓」（＝不太可行）。「Good morning」用 morning 做同字陷阱；「It meets in Room Four」答的是地點，沒回應提議。", "src": "C1"},
  {"q": "Can you show the new accountant where everything is?", "opts": ["Sure, once I finish this e-mail.", "Everything is on sale today.", "The account was closed last year."], "ans": 0, "sk": "l2-req", "exp": "請對方帶新會計認識環境，答「好，等我寫完這封信」＝答應。「Everything is on sale」重複 everything；「account」和 accountant 是拆字陷阱。", "src": "C1"},
  {"q": "The air in this room feels a bit stuffy.", "opts": ["Should I prop the door open?", "Air travel is getting expensive.", "It's the biggest room on this floor."], "ans": 0, "sk": "l2-stmt", "exp": "說房間有點悶（stuffy），用反問「要不要我把門撐開？」回應，提出解決方法。「Air travel…」用 air 做同字陷阱；「It's the biggest room…」重複 room，沒回應悶熱的問題。", "src": "C1"},
  {"q": "I'm afraid we've run out of blue folders.", "opts": ["The green ones will do.", "He folded the letter neatly.", "We'll be out until three."], "ans": 0, "sk": "l2-stmt", "exp": "說藍色資料夾用完了（run out of），答「綠色的也可以」。「folded」（摺）和 folders 發音相近；「We'll be out until three」的 out 是「外出」，同字不同義。", "src": "C1"},
  {"q": "The new coffee machine is much easier to use.", "opts": ["And it's a lot quieter, too.", "Use the side entrance, please.", "Two sugars, please."], "ans": 0, "sk": "l2-stmt", "exp": "稱讚新咖啡機好用多了，附和「而且也安靜很多」。「Use the side entrance」用 use 做同字陷阱；「Two sugars, please」由 coffee 聯想到點咖啡，答非所問。", "src": "C1"},
  {"q": "Our sales numbers dropped in the northern region.", "opts": ["Has anyone looked into why?", "I dropped it off this morning.", "Head north on Route Nine."], "ans": 0, "sk": "l2-stmt", "exp": "說北區業績下滑，用反問「有人查過原因嗎？」回應。「dropped it off」（送過去）用 drop 做同字不同義陷阱；「Head north…」由 northern 聯想到方向，是在指路。", "src": "C1"},
  {"q": "I still haven't heard back from the hotel about our group rate.", "opts": ["Maybe call them directly.", "The growth rate was impressive.", "A group of twelve, I think."], "ans": 0, "sk": "l2-stmt", "exp": "說飯店一直沒回覆團體房價，建議「也許直接打電話給他們」。「growth rate」用 rate 做同字陷阱；「A group of twelve」用 group 做同字陷阱，答的是人數。", "src": "C1"},
  {"q": "The museum's closed for a private event today.", "opts": ["Then let's visit the gardens instead.", "It closes at five on weekdays.", "The event was a huge success."], "ans": 0, "sk": "l2-stmt", "exp": "說博物館今天因私人活動閉館，回應「那我們改去逛花園吧」。「It closes at five…」由 closed 聯想到閉館時間，但今天根本沒開；「The event was a huge success」用過去式評論活動，和「今天正在辦」對不上。", "src": "C1"},
  {"q": "I've never been to the Madrid office before.", "opts": ["I can send you directions.", "The office supplies are running low.", "It was never delivered."], "ans": 0, "sk": "l2-stmt", "exp": "說自己沒去過馬德里辦公室，回應「我可以把路線傳給你」。「The office supplies…」重複 office；「It was never delivered」重複 never，答非所問。", "src": "C1"},
  {"q": "Our competitor just lowered their prices.", "opts": ["Do you know by how much?", "Lower the volume, please.", "The competition starts at noon."], "ans": 0, "sk": "l2-stmt", "exp": "說競爭對手剛降價，用反問「你知道降了多少嗎？」回應。「Lower the volume」用 lower 做同字陷阱（調低音量）；「competition」（比賽）和 competitor 同字根，答的是時間。", "src": "C1"},
  {"q": "Someone left an umbrella in the meeting room.", "opts": ["Put it in the lost and found.", "It might rain later this afternoon.", "The room holds about twenty."], "ans": 0, "sk": "l2-stmt", "exp": "說有人把傘留在會議室，回應「放到失物招領處吧」。「It might rain…」由 umbrella 聯想到下雨；「The room holds about twenty」重複 room，說的是容納人數。", "src": "C1"},
];

